class Solution:
    def maximumCostSubstring(self, s: str, chars: str, vals: List[int]) -> int:
        val = dict(zip(chars, vals))
        ans = cur = 0
        for ch in s:
            w = val.get(ch, ord(ch) - 96)
            cur = max(0, cur + w)
            ans = max(ans, cur)
        return ans

