class Solution {
public:
    int maximumCostSubstring(string s, string chars, vector<int>& vals) {
        int val[26];
        for (int i = 0; i < 26; i++) val[i] = i + 1;
        for (int i = 0; i < (int)chars.size(); i++) val[chars[i] - 'a'] = vals[i];
        int ans = 0, cur = 0;
        for (char c : s) {
            cur = max(0, cur + val[c - 'a']);
            ans = max(ans, cur);
        }
        return ans;
    }
};

