var maximumCostSubstring = function(s, chars, vals) {
    const val = {};
    for (let i = 0; i < 26; i++) val[String.fromCharCode(97 + i)] = i + 1;
    chars.split('').forEach((c, i) => val[c] = vals[i]);
    let ans = 0, cur = 0;
    for (const c of s) {
        cur = Math.max(0, cur + val[c]);
        ans = Math.max(ans, cur);
    }
    return ans;
};
